import {SearchIcon} from '@primer/octicons-react'
import {AnchoredOverlay, TextInput} from '@primer/react'
import {useMemo, useState} from 'react'

import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'
import styles from './ColorPickerItem.module.css'
import {colors} from './utils/colors'

interface ColorPickerItemProps {
  label: string
  value: string | null
  onChange: (color: {name: string; step: string; value: string}) => void
}

export function ColorPickerItem(props: ColorPickerItemProps) {
  const {value, onChange} = props
  const readOnly = useReadOnly(ReadOnlyKey.THEME_PANEL)

  const [open, setOpen] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')

  const activeValue = useMemo(() => {
    for (const [colorName, colorSteps] of Object.entries(colors)) {
      for (const [step, stepValue] of Object.entries(colorSteps)) {
        if (value === stepValue || value?.endsWith(`-${colorName}-${step}`)) {
          return stepValue
        }
      }
    }

    return value
  }, [value])

  const filteredColors = useMemo(() => {
    if (!searchTerm) return colors

    const searchLower = searchTerm.toLowerCase()
    return Object.fromEntries(Object.entries(colors).filter(([name]) => name.toLowerCase().includes(searchLower)))
  }, [searchTerm])

  return (
    <AnchoredOverlay
      open={open}
      onOpen={() => setOpen(true)}
      onClose={() => {
        setOpen(false)
        setSearchTerm('')
      }}
      renderAnchor={anchorProps => (
        <button {...anchorProps} className={styles.trigger} disabled={readOnly} aria-label="Color picker">
          <span className="sr-only">{props.label}</span>
          <span
            className={styles.triggerColor}
            style={{backgroundColor: activeValue ?? undefined}}
            data-empty={activeValue === null}
          />
        </button>
      )}
    >
      <div className={styles.pickerContainer}>
        <TextInput
          leadingVisual={SearchIcon}
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          placeholder="Search colors..."
        />
        {Object.entries(filteredColors).map(([colorName, colorSteps]) => {
          return (
            <div key={colorName} className={styles.colorContainer}>
              <div className={styles.sectionHeading}>{colorName}</div>
              <div className={styles.colorList}>
                {Object.entries(colorSteps).map(([step, stepValue]) => {
                  const selected = value === stepValue || value?.endsWith(`-${colorName}-${step}`)
                  return (
                    <button
                      key={`${colorName}-${step}`}
                      className={styles.colorItem}
                      onClick={() => {
                        onChange({name: colorName, step, value: stepValue})
                        setOpen(false)
                      }}
                      aria-label={stepValue}
                      data-selected={selected}
                      style={{
                        '--color': stepValue,
                      }}
                    />
                  )
                })}
              </div>
            </div>
          )
        })}
      </div>
    </AnchoredOverlay>
  )
}

try{ ColorPickerItem.displayName ||= 'ColorPickerItem' } catch {}